/* Runtime for the translated 68k code (generated by tools/lift.py).
   Machine state: D[], A[] (A[7] is the 68k stack pointer), condition flags as 0/1 values, guest RAM. */
#ifndef LIFTRT_H
#define LIFTRT_H
#include <stdint.h>
#include <setjmp.h>
typedef uint32_t u32; typedef int32_t s32; typedef uint16_t u16; typedef int16_t s16; typedef uint8_t u8; typedef int8_t s8; typedef uint64_t u64; typedef int64_t s64;

extern uint8_t ram[];
extern u32 D[8], A[8], SB[16], REL_A4, REL_A5;
extern u32 fX, fN, fZ, fV, fC;

static inline u32 m8(u32 a)  { return ram[a & 0xFFFFFF]; }
static inline u32 m16(u32 a) { a &= 0xFFFFFF; return (ram[a] << 8) | ram[a + 1]; }
static inline u32 m32(u32 a) { a &= 0xFFFFFF; return ((u32)ram[a] << 24) | (ram[a + 1] << 16) | (ram[a + 2] << 8) | ram[a + 3]; }
static inline void w8(u32 a, u32 v)  { ram[a & 0xFFFFFF] = v; }
static inline void w16(u32 a, u32 v) { a &= 0xFFFFFF; ram[a] = v >> 8; ram[a + 1] = v; }
static inline void w32(u32 a, u32 v) { a &= 0xFFFFFF; ram[a] = v >> 24; ram[a + 1] = v >> 16; ram[a + 2] = v >> 8; ram[a + 3] = v; }

typedef void (*LiftFn)(void);
typedef struct { int seg; u32 off; LiftFn fn; } LiftEnt;
extern const LiftEnt lift_ents[]; extern const int lift_nents;
typedef struct { int seg; u32 off; LiftFn fn; int haslink; } LiftMid;
extern const LiftMid lift_mids[]; extern const int lift_nmids;
extern u32 lift_mid, lift_mid_r0; extern const char *lift_mm_fn;
extern const unsigned char lift_mdrv_sig[16]; extern const unsigned lift_mdrv_len;
extern const unsigned char lift_smod_sig[16]; extern const unsigned lift_smod_len;

/* host glue (port/lift_host.inc) */
void lift_enter(u32 target);                    /* run translated routine at runtime address, or bail to the interpreter */
void lift_trap(u32 w, u32 trap_pc, u32 ret);    /* A-line trap executed from translated code */
u32 lift_get_sr(void); void lift_set_sr(u32 v);
void lift_bail(u32 pc) __attribute__((noreturn));
void lift_ret_mismatch(u32 r) __attribute__((noreturn)); void lift_ret_mismatch2(u32 r, u32 r0) __attribute__((noreturn));

#define LPUSH(ret)      do { A[7] -= 4; w32(A[7], (ret)); } while (0)
extern u32 lift_rs[256]; extern int lift_rsp; extern u32 lift_ret_pc;
extern int lift_loopcnt; void lift_poll(u32 resume_pc);
#define LLOOP(pc) do { if (++lift_loopcnt > 3000) lift_poll(pc); } while (0)
#define LCALL(tgt, ret) do { u32 t_ = (tgt); LPUSH(ret); lift_rs[lift_rsp++ & 255] = (ret); lift_enter(t_); lift_rsp--; } while (0)
extern int lift_dry; void lift_note(LiftFn f);
#ifdef LIFT_TRACE
void lift_trace(u32 pc);
#define LTR(a) lift_trace(SB[LSEG] + (a) - (0x100000 + LSEG * 0x10000))
#else
#define LTR(a)
#endif
#define LSCALL(ret, fn) do { LPUSH(ret); if (lift_dry) lift_note(fn); lift_rs[lift_rsp++ & 255] = (ret); fn(); lift_rsp--; } while (0)
#define LTAIL(tgt)      do { lift_enter(tgt); return; } while (0)
#define LJMP_DYN(tgt)   do { u32 t_ = (tgt); if (lift_rsp > 0 && t_ == lift_rs[(lift_rsp - 1) & 255]) return; lift_enter(t_); return; } while (0)
#define LBAIL(pc)       lift_bail(pc)
#define LTRAP(w, tpc, ret) lift_trap(w, tpc, ret)
#define LRTS()          do { u32 r_ = m32(A[7]); A[7] += 4; lift_ret_pc = r_; if (lift_rsp > 0 && r_ != lift_rs[(lift_rsp - 1) & 255]) lift_bail(r_); return; } while (0)
#define LRTD(n)         do { u32 r_ = m32(A[7]); A[7] += 4 + (n); lift_ret_pc = r_; if (lift_rsp > 0 && r_ != lift_rs[(lift_rsp - 1) & 255]) lift_bail(r_); return; } while (0)

#define MK(sz) ((sz) == 1 ? 0xFFu : (sz) == 2 ? 0xFFFFu : 0xFFFFFFFFu)
#define SG(sz) ((sz) == 1 ? 0x80u : (sz) == 2 ? 0x8000u : 0x80000000u)
#define LNZ(r, sz) do { u32 q_ = (r) & MK(sz); fN = (q_ & SG(sz)) != 0; fZ = q_ == 0; } while (0)

#define LC_HI (!fC && !fZ)
#define LC_LS (fC || fZ)
#define LC_CC (!fC)
#define LC_CS (fC)
#define LC_NE (!fZ)
#define LC_EQ (fZ)
#define LC_VC (!fV)
#define LC_VS (fV)
#define LC_PL (!fN)
#define LC_MI (fN)
#define LC_GE (fN == fV)
#define LC_LT (fN != fV)
#define LC_GT (!fZ && fN == fV)
#define LC_LE (fZ || fN != fV)

static inline u32 L_logic(u32 r, int sz) { r &= MK(sz); fN = (r & SG(sz)) != 0; fZ = r == 0; fV = fC = 0; return r; }
static inline u32 L_add(u32 s, u32 d, int sz) {
    u32 m = MK(sz); s &= m; d &= m; u64 t = (u64)s + d; u32 r = (u32)t & m;
    fC = fX = t > m; fV = (((s ^ r) & (d ^ r)) & SG(sz)) != 0; fN = (r & SG(sz)) != 0; fZ = r == 0; return r;
}
static inline u32 L_sub(u32 s, u32 d, int sz) {      /* d - s */
    u32 m = MK(sz); s &= m; d &= m; u32 r = (d - s) & m;
    fC = fX = s > d; fV = (((s ^ d) & (r ^ d)) & SG(sz)) != 0; fN = (r & SG(sz)) != 0; fZ = r == 0; return r;
}
static inline void L_cmp(u32 s, u32 d, int sz) {
    u32 m = MK(sz); s &= m; d &= m; u32 r = (d - s) & m;
    fC = s > d; fV = (((s ^ d) & (r ^ d)) & SG(sz)) != 0; fN = (r & SG(sz)) != 0; fZ = r == 0;
}
static inline u32 L_neg(u32 d, int sz) { return L_sub(d, 0, sz); }
static inline u32 L_negx(u32 d, int sz) {
    u32 m = MK(sz); d &= m; u64 sub = (u64)d + fX; u32 r = (u32)(0 - sub) & m;
    fC = fX = sub != 0; fV = ((d & r) & SG(sz)) != 0; fN = (r & SG(sz)) != 0; if (r) fZ = 0; return r;
}

/* shifts and rotates: v = register value (masked to size here), n = count */
static inline u32 L_lsl(u32 v, u32 n, int sz) {
    u32 m = MK(sz); int bits = sz * 8; v &= m; n &= 63; u32 r, c;
    if (n == 0) { fN = (v & SG(sz)) != 0; fZ = v == 0; fV = fC = 0; return v; }
    if (n > (u32)bits) { r = 0; c = 0; } else { c = (v >> (bits - n)) & 1; r = n == (u32)bits ? 0 : (v << n) & m; }
    fX = fC = c; fV = 0; fN = (r & SG(sz)) != 0; fZ = r == 0; return r;
}
static inline u32 L_lsr(u32 v, u32 n, int sz) {
    u32 m = MK(sz); int bits = sz * 8; v &= m; n &= 63; u32 r, c;
    if (n == 0) { fN = (v & SG(sz)) != 0; fZ = v == 0; fV = fC = 0; return v; }
    if (n > (u32)bits) { r = 0; c = 0; } else { c = (v >> (n - 1)) & 1; r = n == (u32)bits ? 0 : v >> n; }
    fX = fC = c; fV = 0; fN = (r & SG(sz)) != 0; fZ = r == 0; return r;
}
static inline u32 L_asr(u32 v, u32 n, int sz) {
    u32 m = MK(sz); int bits = sz * 8; v &= m; n &= 63; u32 r, c; int neg = (v & SG(sz)) != 0;
    if (n == 0) { fN = neg; fZ = v == 0; fV = fC = 0; return v; }
    if (n >= (u32)bits) { r = neg ? m : 0; c = neg; } else { s32 sv = (s32)(sz == 1 ? (u32)(s32)(s8)v : sz == 2 ? (u32)(s32)(s16)v : v); r = (u32)(sv >> n) & m; c = (v >> (n - 1)) & 1; }
    fX = fC = c; fV = 0; fN = (r & SG(sz)) != 0; fZ = r == 0; return r;
}
static inline u32 L_asl(u32 v, u32 n, int sz) {
    u32 m = MK(sz); int bits = sz * 8; v &= m; n &= 63; u32 r, c, ov;
    if (n == 0) { fN = (v & SG(sz)) != 0; fZ = v == 0; fV = fC = 0; return v; }
    if (n >= (u32)bits + 1) { r = 0; c = 0; ov = v != 0; }
    else {
        c = n == (u32)bits ? (v & 1) : ((v >> (bits - n)) & 1); r = n >= (u32)bits ? 0 : (v << n) & m;
        u32 top = (n >= (u32)bits) ? m : (((m << (bits - n - 1)) & m) | 0);       /* the n+1 most significant bits */
        if (n < (u32)bits) top = m & ~((1u << (bits - n - 1)) - 1);
        u32 t = v & top; ov = !(t == 0 || t == top);
    }
    fX = fC = c; fV = ov; fN = (r & SG(sz)) != 0; fZ = r == 0; return r;
}
static inline u32 L_rol(u32 v, u32 n, int sz) {
    u32 m = MK(sz); int bits = sz * 8; v &= m; n &= 63; u32 k = n % bits, r = v;
    if (k) r = ((v << k) | (v >> (bits - k))) & m;
    fN = (r & SG(sz)) != 0; fZ = r == 0; fV = 0; fC = n ? (r & 1) : 0; return r;
}
static inline u32 L_ror(u32 v, u32 n, int sz) {
    u32 m = MK(sz); int bits = sz * 8; v &= m; n &= 63; u32 k = n % bits, r = v;
    if (k) r = ((v >> k) | (v << (bits - k))) & m;
    fN = (r & SG(sz)) != 0; fZ = r == 0; fV = 0; fC = n ? ((r & SG(sz)) != 0) : 0; return r;
}

static inline u32 L_roxl(u32 v, u32 n, int sz) {
    u32 m = MK(sz); int bits = sz * 8; v &= m; n &= 63; n %= (u32)(bits + 1);
    if (n == 0) { fC = fX; fN = (v & SG(sz)) != 0; fZ = v == 0; fV = 0; return v; }
    for (u32 i = 0; i < n; i++) { u32 c = (v & SG(sz)) != 0; v = ((v << 1) | fX) & m; fX = c; }
    fC = fX; fN = (v & SG(sz)) != 0; fZ = v == 0; fV = 0; return v;
}
static inline u32 L_roxr(u32 v, u32 n, int sz) {
    u32 m = MK(sz); int bits = sz * 8; v &= m; n &= 63; n %= (u32)(bits + 1);
    if (n == 0) { fC = fX; fN = (v & SG(sz)) != 0; fZ = v == 0; fV = 0; return v; }
    for (u32 i = 0; i < n; i++) { u32 c = v & 1; v = (v >> 1) | (fX ? SG(sz) : 0); fX = c; }
    fC = fX; fN = (v & SG(sz)) != 0; fZ = v == 0; fV = 0; return v;
}
static inline u32 L_addx(u32 s, u32 d, int sz) {
    u32 m = MK(sz); s &= m; d &= m; u64 t = (u64)s + d + fX; u32 r = (u32)t & m;
    fX = fC = (t >> (sz * 8)) & 1; fV = ((~(s ^ d) & (s ^ r)) & SG(sz)) != 0; fN = (r & SG(sz)) != 0; if (r) fZ = 0; return r;
}
static inline u32 L_subx(u32 s, u32 d, int sz) {
    u32 m = MK(sz); s &= m; d &= m; u32 r = (d - s - fX) & m;
    fX = fC = (u64)s + fX > d; fV = (((d ^ s) & (d ^ r)) & SG(sz)) != 0; fN = (r & SG(sz)) != 0; if (r) fZ = 0; return r;
}
static inline void L_ccr_op(int op, u32 imm) {       /* 0=and 1=or 2=eor on the CCR */
    u32 c = (fX << 4) | (fN << 3) | (fZ << 2) | (fV << 1) | fC;
    c = op == 0 ? (c & imm) : op == 1 ? (c | imm) : (c ^ imm);
    fX = (c >> 4) & 1; fN = (c >> 3) & 1; fZ = (c >> 2) & 1; fV = (c >> 1) & 1; fC = c & 1;
}

/* multiply / divide (return nonzero when the interpreter must handle it: divide by zero) */
static inline u32 L_mulu16(u32 s, u32 d) { u32 r = (s & 0xFFFF) * (d & 0xFFFF); fN = r >> 31; fZ = r == 0; fV = fC = 0; return r; }
static inline u32 L_muls16(u32 s, u32 d) { u32 r = (u32)((s32)(s16)s * (s32)(s16)d); fN = r >> 31; fZ = r == 0; fV = fC = 0; return r; }
static inline u32 L_mulu32(u32 s, u32 d) { u64 p = (u64)s * d; u32 r = (u32)p; fN = r >> 31; fZ = r == 0; fV = (p >> 32) != 0; fC = 0; return r; }
static inline u32 L_muls32(u32 s, u32 d) { s64 p = (s64)(s32)s * (s32)d; u32 r = (u32)p; fN = r >> 31; fZ = r == 0; fV = p != (s64)(s32)r; fC = 0; return r; }
/* returns 0 ok, 1 divide by zero (interpreter must raise it), 2 overflow (V set, registers unchanged) */
static inline int L_divu16(u32 s, u32 d, u32 *out) {
    s &= 0xFFFF; if (!s) return 1; u32 q = d / s, rem = d % s;
    if (q > 0xFFFF) { fV = 1; fC = 0; return 2; }
    fN = (q & 0x8000) != 0; fZ = q == 0; fV = fC = 0; *out = (rem << 16) | q; return 0;
}
static inline int L_divs16(u32 s, u32 d, u32 *out) {
    s32 dv = (s32)(s16)s; if (!dv) return 1; s32 dd = (s32)d; s64 q = (s64)dd / dv; s64 rem = (s64)dd % dv;
    if (q > 32767 || q < -32768) { fV = 1; fC = 0; return 2; }
    fN = (q & 0x8000) != 0; fZ = q == 0; fV = fC = 0; *out = ((u32)rem << 16) | ((u32)q & 0xFFFF); return 0;
}
static inline int L_divu32(u32 s, u32 d, u32 *q, u32 *r) { if (!s) return 1; *q = d / s; *r = d % s; fN = *q >> 31; fZ = *q == 0; fV = fC = 0; return 0; }
static inline int L_divs32(u32 s, u32 d, u32 *q, u32 *r) {
    s32 dv = (s32)s; if (!dv) return 1; s64 qq = (s64)(s32)d / dv; if (qq > 2147483647LL || qq < -2147483648LL) { fV = 1; fC = 0; return 2; }
    *q = (u32)qq; *r = (u32)((s64)(s32)d % dv); fN = *q >> 31; fZ = qq == 0; fV = fC = 0; return 0;
}

/* bit fields */
#define BF_MASK(w) ((w) == 32 ? 0xFFFFFFFFu : ((1u << (w)) - 1))
#define LBF_FLAGS(f, w) do { fN = ((f) >> ((w) - 1)) & 1; fZ = (f) == 0; fV = fC = 0; } while (0)
static inline u32 bf_rol(u32 v, u32 k) { k &= 31; return k ? (v << k) | (v >> (32 - k)) : v; }
static inline u32 BF_GET_D(u32 v, u32 off, u32 w) { u32 r = bf_rol(v, off); return w == 32 ? r : r >> (32 - w); }
static inline void BF_PUT_D(u32 *d, u32 off, u32 w, u32 val) {
    u32 r = bf_rol(*d, off), m = BF_MASK(w); u32 sh = 32 - w;
    r = (r & ~(m << sh)) | ((val & m) << sh); *d = bf_rol(r, 32 - (off & 31));
}
static inline u32 BF_GET_M(u32 ea, s32 off, u32 w) {
    u32 a = ea + (u32)(off >> 3); u32 bit = off & 7; u64 v = 0; for (int i = 0; i < 5; i++) v = (v << 8) | m8(a + i);
    return (u32)((v >> (40 - bit - w)) & BF_MASK(w));
}
static inline void BF_PUT_M(u32 ea, s32 off, u32 w, u32 val) {
    u32 a = ea + (u32)(off >> 3); u32 bit = off & 7; u64 v = 0; for (int i = 0; i < 5; i++) v = (v << 8) | m8(a + i);
    u32 nb = (bit + w + 7) / 8; int sh = 40 - bit - w; u64 mk = (u64)BF_MASK(w) << sh; v = (v & ~mk) | (((u64)(val & BF_MASK(w))) << sh);
    for (u32 i = 0; i < nb; i++) w8(a + i, (u32)(v >> (32 - 8 * i)));
}
static inline u32 BF_FFO_RES(u32 f, u32 off, u32 w) { if (!f) return off + w; int lz = __builtin_clz(f) - (32 - (int)w); return off + lz; }
#endif

extern unsigned char lift_fcov[16][1 << 15];
#define LCOV(o) (lift_fcov[LSEG][(o) & 0x7FFF] = 1)
